  assert.deepEqual(applyPatch([1, 2], [{ op: 'add', path: '/2', value: 9 }]), [1, 2, 9]);
  assert.deepEqual(applyPatch([1], [{ op: 'add', path: '/-', value: 9 }]), [1, 9]);
